/*
 * model.js — 3D models (GLB) embedded as base64
 * ใช้ได้กับ Three.js (GLTFLoader), <model-viewer>, Babylon.js ฯลฯ
 *
 * วิธีใช้ (ใส่ <script src="model.js"></script> ก่อนสคริปต์ของคุณ):
 *   MODELS.list()                  -> รายชื่อ key ทั้งหมด
 *   MODELS.url("clownfish")        -> blob URL (ใช้กับ loader.load(url) หรือ <model-viewer src=...>)
 *   MODELS.buffer("clownfish")     -> ArrayBuffer (ใช้กับ loader.parse(buffer, "", onLoad))
 *   MODELS.info("clownfish")       -> { name, bytes }
 *   MODELS.data.clownfish          -> base64 string ดิบ
 */
(function (root) {
  "use strict";
  var data = {};
  var names = {};
  names["adventurer"] = "Adventurer (Quaternius)";
  data["adventurer"] = "";
  names["animatedWoman"] = "Animated Woman (Quaternius)";
  data["animatedWoman"] = "";
  names["anglerfish"] = "Anglerfish (Quaternius)";
  data["anglerfish"] = "";
  names["blackLionFish"] = "Black Lion Fish (Quaternius)";
  data["blackLionFish"] = "";
  names["blobfish"] = "Blobfish (Quaternius)";
  data["blobfish"] = "";
  names["blueGoldfish"] = "Blue Goldfish (Quaternius)";
  data["blueGoldfish"] = "";
  names["butterflyFish"] = "Butterfly Fish (Quaternius)";
  data["butterflyFish"] = "";
  names["cardinalFish"] = "Cardinal Fish (Quaternius)";
  data["cardinalFish"] = "";
  names["clownfish"] = "Clownfish (Quaternius)";
  data["clownfish"] = "";
  names["dolphin"] = "Dolphin (Quaternius)";
  data["dolphin"] = "";
  names["fish"] = "Fish (Quaternius)";
  data["fish"] = "";
  names["fishHook"] = "Fish hook (Poly by Google)";
  data["fishHook"] = "";
  names["fishingRod1"] = "Fishing Rod Lvl1 (Quaternius)";
  data["fishingRod1"] = "";
  names["fishingRod2"] = "Fishing Rod Lvl2 (Quaternius)";
  data["fishingRod2"] = "";
  names["fishingRod3"] = "Fishing Rod Lvl3 (Quaternius)";
  data["fishingRod3"] = "";
  names["fishingRod4"] = "Fishing Rod Lvl4 (Quaternius)";
  data["fishingRod4"] = "";
  names["fishingRod5"] = "Fishing Rod Lvl5 (Quaternius)";
  data["fishingRod5"] = "";
  names["fishingPoleJeremy"] = "Fishing pole (jeremy)";
  data["fishingPoleJeremy"] = "";
  names["fishingPoleShawn"] = "Fishing Pole (Shawn Westphal)";
  data["fishingPoleShawn"] = "";
  names["fishingRodJustin"] = "Fishing rod (Justin Randall)";
  data["fishingRodJustin"] = "";

  var urlCache = {};

  function check(key) {
    if (!Object.prototype.hasOwnProperty.call(data, key)) {
      throw new Error("MODELS: ไม่พบโมเดล '" + key + "' (ดู MODELS.list())");
    }
  }

  function buffer(key) {
    check(key);
    var bin = atob(data[key]);
    var bytes = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes.buffer;
  }

  function url(key) {
    check(key);
    if (!urlCache[key]) {
      urlCache[key] = URL.createObjectURL(new Blob([buffer(key)], { type: "model/gltf-binary" }));
    }
    return urlCache[key];
  }

  function info(key) {
    check(key);
    var b64 = data[key];
    var pad = b64.endsWith("==") ? 2 : b64.endsWith("=") ? 1 : 0;
    return { name: names[key], bytes: (b64.length * 3) / 4 - pad };
  }

  var api = {
    data: data,
    names: names,
    list: function () { return Object.keys(data); },
    buffer: buffer,
    url: url,
    info: info
  };

  root.MODELS = api;
  if (typeof module !== "undefined" && module.exports) module.exports = api;
})(typeof globalThis !== "undefined" ? globalThis : typeof window !== "undefined" ? window : this);
